import { type ClassValue, clsx } from 'clsx'
import { twMerge } from 'tailwind-merge'

/**
 * shadcn/shadcn-style class merge helper.
 *
 * Required by every component under components/ui (and generated by the
 * shadcn CLI). Lives at @/lib/utils because components.json points
 * `aliases.utils` here.
 */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}
